cd /workspace && python3 - <<'EOF'
import re
src = open("submission/main.py").read()
src = src.replace("from fractions import Fraction\n", "from fractions import Fraction\nfrom operator import mul\n")
old = """            best = 0
            any_neg = True
            for j in range(nstarts):
                z = base
                for k in range(K):
                    z += pf[k][rows[j + k]]
                if sh > 1:
                    if z >= 0:
                        z = (z + half) // sh
                    else:
                        z = -((-z + half) // sh)
                if z < 0:
                    z = 0
                elif z > 127:
                    z = 127
                    any_neg = False
                    best = z
                    break
                else:
                    any_neg = False
                if z > best:
                    best = z
            if best == 0 and any_neg:
                # all activations clamped to zero (or genuinely zero)
                best = 0
            pooled.append(best)"""
new = """            best = -1
            for j in range(nstarts):
                z = base
                for k in range(K):
                    z += pf[k][rows[j + k]]
                if sh > 1:
                    if z >= 0:
                        z = (z + half) // sh
                    else:
                        z = -((-z + half) // sh)
                if z < 0:
                    z = 0
                elif z > 127:
                    best = 127
                    break
                if z > best:
                    best = z
            pooled.append(best)"""
assert old in src
src = src.replace(old, new)
open("submission/main.py","w").write(src)
EOF
cd /workspace && python3 submission/main.py < examples/input.json > tmp/actual.json && python3 -c '
import json
a=json.load(open("tmp/actual.json")); b=json.load(open("examples/expected.json"))
print("MATCH" if a==b else "MISMATCH")
if a!=b:
    for k in b:
        if a.get(k)!=b[k]:
            print("key differs:",k)
            print(" got:",json.dumps(a.get(k))[:1500])
            print(" exp:",json.dumps(b[k])[:1500])
'

